"use client";
import * as React from "react";
import { cn } from "@/lib/utils";
import { sculptureNumber } from "@/lib/cojeev/sculpture-raster";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import { Slider, SliderOutput } from "@/components/ui/slider";
import { Label } from "@/components/ui/label";
import { Meta } from "@/components/ui/typography";

export type SculptureView = { turn: number; pitch: number; zoom: number };
export type SculptureOrbitProps = Omit<React.ComponentPropsWithoutRef<"div">, "children" | "defaultValue" | "onChange"> & {
  children: (view: SculptureView & { interacting: boolean }) => React.ReactNode;
  value?: SculptureView;
  defaultValue?: Partial<SculptureView>;
  onValueChange?: (view: SculptureView) => void;
  disabled?: boolean;
  label?: string;
};
export function normalizeSculptureView(view: Partial<SculptureView> = {}): SculptureView {
  const turn = Number.isFinite(view.turn) ? ((view.turn! + 180) % 360 + 360) % 360 - 180 : 0;
  return { turn, pitch: sculptureNumber(view.pitch, 0, -80, 80), zoom: sculptureNumber(view.zoom, 1, .6, 1.15) };
}

/** Explicit orbit stays usable in every stillness mode; touch keeps vertical page scrolling. */
export function SculptureOrbit({ children, value, defaultValue, onValueChange, disabled = false, label = "Sculpture view", className, ...props }: SculptureOrbitProps) {
  const [local, setLocal] = React.useState(() => normalizeSculptureView(defaultValue)), [interacting, setInteracting] = React.useState(false);
  const [disabledSnapshot, setDisabledSnapshot] = React.useState(disabled);
  // Cancel rendered gesture state as the prop changes; it must not revive on re-enable.
  if (disabledSnapshot !== disabled) { setDisabledSnapshot(disabled); if (disabled) setInteracting(false); }
  const view = React.useMemo(() => normalizeSculptureView(value ?? local), [value, local]), latest = React.useRef(view), viewport = React.useRef<HTMLDivElement>(null), id = React.useId();
  const gesture = React.useRef<{ id: number; x: number; y: number; initial: SculptureView; touch: boolean; captured: boolean } | null>(null);
  React.useEffect(() => { latest.current = view; }, [view]);
  const stop = React.useCallback(() => {
    const current = gesture.current; gesture.current = null; setInteracting(false);
    if (current && viewport.current?.hasPointerCapture(current.id)) viewport.current.releasePointerCapture(current.id);
  }, []);
  React.useEffect(() => {
    if (!disabled) return;
    const current = gesture.current; gesture.current = null;
    if (current && viewport.current?.hasPointerCapture(current.id)) viewport.current.releasePointerCapture(current.id);
  }, [disabled]);
  React.useEffect(() => { const hidden = () => { if (document.hidden) stop(); }; window.addEventListener("blur", stop); document.addEventListener("visibilitychange", hidden); return () => { window.removeEventListener("blur", stop); document.removeEventListener("visibilitychange", hidden); }; }, [stop]);
  function change(next: Partial<SculptureView>) {
    if (disabled) return;
    const normalized = normalizeSculptureView({ ...latest.current, ...next }); latest.current = normalized;
    if (value === undefined) setLocal(normalized);
    onValueChange?.(normalized);
  }
  const reset = () => change({ turn: 0, pitch: 0, zoom: 1 });
  return <div {...props} className={cn("v-sculpture-orbit", className)} data-slot="sculpture-orbit" data-disabled={disabled || undefined} role="group" aria-label={label}>
    <div ref={viewport} className="v-sculpture-orbit-view" data-slot="sculpture-orbit-viewport" role="group" aria-label={`${label}: rotation`} aria-describedby={`${id}-help`} aria-disabled={disabled || undefined} tabIndex={disabled ? -1 : 0} data-dragging={interacting && !disabled || undefined}
      onPointerDown={event => {
        if (disabled || event.button !== 0 || !event.isPrimary) return;
        const touch = event.pointerType === "touch";
        gesture.current = { id: event.pointerId, x: event.clientX, y: event.clientY, initial: latest.current, touch, captured: !touch };
        if (!touch) { event.currentTarget.setPointerCapture(event.pointerId); event.currentTarget.focus({ preventScroll: true }); setInteracting(true); }
      }}
      onPointerMove={event => {
        const current = gesture.current;
        if (disabled || !current || current.id !== event.pointerId) return;
        const dx = event.clientX - current.x, dy = event.clientY - current.y;
        if (current.touch && !current.captured) {
          if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 7) { stop(); return; }
          if (Math.abs(dx) < 7) return;
          event.currentTarget.setPointerCapture(event.pointerId); current.captured = true; setInteracting(true);
        }
        const width = Math.max(200, event.currentTarget.clientWidth);
        change({ turn: current.initial.turn + dx / width * 240, pitch: current.touch ? current.initial.pitch : current.initial.pitch + dy / width * 160 });
      }}
      onPointerUp={stop} onPointerCancel={stop} onLostPointerCapture={stop}
      onKeyDown={event => {
        if (disabled || event.altKey || event.ctrlKey || event.metaKey) return;
        const step = event.shiftKey ? 20 : 5;
        if (event.key === "ArrowLeft") change({ turn: latest.current.turn - step });
        else if (event.key === "ArrowRight") change({ turn: latest.current.turn + step });
        else if (event.key === "ArrowUp") change({ pitch: latest.current.pitch - step });
        else if (event.key === "ArrowDown") change({ pitch: latest.current.pitch + step });
        else if (event.key === "+" || event.key === "=") change({ zoom: latest.current.zoom + .05 });
        else if (event.key === "-") change({ zoom: latest.current.zoom - .05 });
        else if (event.key === "Home") reset();
        else return;
        event.preventDefault();
      }}>
      {children({ ...view, interacting: interacting && !disabled })}
    </div>
    <div className="v-sculpture-orbit-tools">
      <div className="v-sculpture-orbit-step" role="group" aria-label="Turn and tilt">
        <Button size="sm" variant="ghost" disabled={disabled} aria-label="Turn left" onClick={() => change({ turn: latest.current.turn - 15 })}><Icon name="arrow-left" /></Button>
        <Button size="sm" variant="ghost" disabled={disabled} aria-label="Turn right" onClick={() => change({ turn: latest.current.turn + 15 })}><Icon name="arrow-right" /></Button>
        <Button size="sm" variant="ghost" disabled={disabled} aria-label="Tilt up" onClick={() => change({ pitch: latest.current.pitch - 10 })}><Icon name="arrow-up" /></Button>
        <Button size="sm" variant="ghost" disabled={disabled} aria-label="Tilt down" onClick={() => change({ pitch: latest.current.pitch + 10 })}><Icon name="arrow-down" /></Button>
      </div>
      <div className="v-sculpture-orbit-zoom"><Label as="span" id={`${id}-zoom`}>Zoom</Label><Slider min={.6} max={1.15} step={.05} value={[view.zoom]} onValueChange={next => change({ zoom: next[0] ?? 1 })} aria-labelledby={`${id}-zoom`} disabled={disabled} /><SliderOutput>{Math.round(view.zoom * 100)}%</SliderOutput></div>
      <Button size="sm" variant="secondary" disabled={disabled} onClick={reset}><Icon name="refresh" />Reset view</Button>
    </div>
    <Meta id={`${id}-help`} className="v-sculpture-orbit-help">Drag to turn. Arrow keys rotate, + / − zoom, Home resets. Touch: swipe sideways to turn.</Meta>
  </div>;
}

import type { SculptureGeometry } from "@/lib/cojeev/sculpture-geometry";

export type SculptureGrid = { columns: number; rows: number; cellWidth: number; cellHeight: number; width: number; height: number };
export type SculptureFrame = { grid: SculptureGrid; coverage: Uint8Array; light: Float32Array; depth: Float32Array; sampling: number };
export const sculptureNumber = (value: number | undefined, fallback: number, min: number, max: number) => Number.isFinite(value) ? Math.max(min, Math.min(max, value!)) : fallback;
export function sculptureGrid(width: number, height: number, step = 2): SculptureGrid {
  width = sculptureNumber(width, 1, 1, 20000); height = sculptureNumber(height, 1, 1, 20000);
  step = Math.max(sculptureNumber(step, 2, 1.5, 12), width / 280, height / 220);
  const columns = Math.max(1, Math.floor(width / step)), rows = Math.max(1, Math.floor(height / step));
  return { columns, rows, cellWidth: width / columns, cellHeight: height / rows, width, height };
}

/** Original orthographic depth pass. The same surface supplies glyphs, print dots and engraved lines. */
export function rasterizeSculpture(mesh: SculptureGeometry, grid: SculptureGrid, yaw = .35, pitch = -.2, zoom = 1): SculptureFrame {
  const { columns, rows, cellWidth, cellHeight, width, height } = grid;
  const coverage = new Uint8Array(columns * rows), depth = new Float32Array(coverage.length).fill(-Infinity), light = new Float32Array(coverage.length);
  const projected = new Float32Array(mesh.positions.length / 3 * 4), cy = Math.cos(yaw), sy = Math.sin(yaw), cx = Math.cos(pitch), sx = Math.sin(pitch);
  const angle = -.14, cz = Math.cos(angle), sz = Math.sin(angle), scale = Math.min(width, height) * .39 * sculptureNumber(zoom, 1, .6, 1.15);
  function rotate(x: number, y: number, z: number) { const a = cy * x + sy * z, b = -sy * x + cy * z, c = cx * y - sx * b; return [cz * a - sz * c, sz * a + cz * c, sx * y + cx * b]; }
  for (let i = 0, out = 0; i < mesh.positions.length; i += 3, out += 4) {
    const p = rotate(mesh.positions[i], mesh.positions[i + 1], mesh.positions[i + 2]), n = rotate(mesh.normals[i], mesh.normals[i + 1], mesh.normals[i + 2]);
    projected[out] = columns / 2 + p[0] * scale / cellWidth; projected[out + 1] = rows / 2 - p[1] * scale / cellHeight; projected[out + 2] = p[2];
    projected[out + 3] = Math.min(1, .12 + .8 * Math.max(0, n[0] * -.42 + n[1] * .58 + n[2] * .69) + .12 * Math.abs(n[2]));
  }
  // Vertex/triangle limits alone cannot bound overlapping triangle work. Estimate
  // clipped coverage first, then lower sampling before any expensive raster pass.
  let work = 0;
  for (let i = 0; i < mesh.triangles.length; i += 3) {
    const a = mesh.triangles[i] * 4, b = mesh.triangles[i + 1] * 4, c = mesh.triangles[i + 2] * 4;
    const left = Math.max(0, Math.floor(Math.min(projected[a], projected[b], projected[c]))), right = Math.min(columns - 1, Math.ceil(Math.max(projected[a], projected[b], projected[c])));
    const top = Math.max(0, Math.floor(Math.min(projected[a + 1], projected[b + 1], projected[c + 1]))), bottom = Math.min(rows - 1, Math.ceil(Math.max(projected[a + 1], projected[b + 1], projected[c + 1])));
    work += Math.max(0, right - left + 1) * Math.max(0, bottom - top + 1);
  }
  if (work > 350000 && (columns > 1 || rows > 1)) {
    const factor = Math.sqrt(work / 350000) * 1.15, lowColumns = Math.max(1, Math.floor(columns / factor)), lowRows = Math.max(1, Math.floor(rows / factor));
    const low = rasterizeSculpture(mesh, { ...grid, columns: lowColumns, rows: lowRows, cellWidth: width / lowColumns, cellHeight: height / lowRows }, yaw, pitch, zoom);
    for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
      const at = Math.min(lowRows - 1, Math.floor(y / rows * lowRows)) * lowColumns + Math.min(lowColumns - 1, Math.floor(x / columns * lowColumns)), i = y * columns + x;
      coverage[i] = low.coverage[at]; light[i] = low.light[at]; depth[i] = low.depth[at];
    }
    return { grid, coverage, depth, light, sampling: Math.max(columns / lowColumns, rows / lowRows) * low.sampling };
  }
  for (let i = 0; i < mesh.triangles.length; i += 3) {
    const a = mesh.triangles[i] * 4, b = mesh.triangles[i + 1] * 4, c = mesh.triangles[i + 2] * 4;
    const ax = projected[a], ay = projected[a + 1], bx = projected[b], by = projected[b + 1], cxp = projected[c], cyp = projected[c + 1];
    const denominator = (by - cyp) * (ax - cxp) + (cxp - bx) * (ay - cyp);
    if (Math.abs(denominator) < 1e-7) continue;
    const left = Math.max(0, Math.floor(Math.min(ax, bx, cxp))), right = Math.min(columns - 1, Math.ceil(Math.max(ax, bx, cxp)));
    const top = Math.max(0, Math.floor(Math.min(ay, by, cyp))), bottom = Math.min(rows - 1, Math.ceil(Math.max(ay, by, cyp)));
    for (let y = top; y <= bottom; y++) for (let x = left; x <= right; x++) {
      const wa = ((by - cyp) * (x + .5 - cxp) + (cxp - bx) * (y + .5 - cyp)) / denominator, wb = ((cyp - ay) * (x + .5 - cxp) + (ax - cxp) * (y + .5 - cyp)) / denominator, wc = 1 - wa - wb;
      if (wa < -.001 || wb < -.001 || wc < -.001) continue;
      const z = wa * projected[a + 2] + wb * projected[b + 2] + wc * projected[c + 2], index = y * columns + x;
      if (z <= depth[index]) continue;
      depth[index] = z; coverage[index] = 1; light[index] = wa * projected[a + 3] + wb * projected[b + 3] + wc * projected[c + 3];
    }
  }
  return { grid, coverage, depth, light, sampling: 1 };
}

export type DitherPattern = "ordered" | "halftone" | "diffusion" | "stipple";
export type InkTreatment = "hatch" | "crosshatch" | "contour";
export type PrintOptions = { kind: "dither" | "ink"; pattern?: DitherPattern; treatment?: InkTreatment; markSize?: number; density?: number; angle?: number; relief?: number };
const bayer = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
const noise = (x: number, y: number) => { const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return n - Math.floor(n); };
const fract = (value: number) => value - Math.floor(value);
export function sculpturePrint(frame: SculptureFrame, options: PrintOptions): Uint8Array {
  const { grid, coverage, light, depth } = frame, { columns, rows, cellWidth, cellHeight } = grid, marks = new Uint8Array(coverage.length);
  const density = sculptureNumber(options.density, 1, .5, 1.6), spacing = sculptureNumber(options.markSize, 8, 4, 16), angle = sculptureNumber(options.angle, -25, -180, 180) * Math.PI / 180, relief = sculptureNumber(options.relief, .55, 0, 1);
  const errors = options.pattern === "diffusion" ? new Float32Array(coverage.length) : undefined;
  for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
    const i = y * columns + x;
    if (!coverage[i]) continue;
    const shade = Math.max(.06, Math.min(.98, (.18 + (1 - light[i]) * .85) * density));
    if (options.kind === "dither") {
      if (errors) {
        const value = shade + errors[i], hit = value >= .5 ? 1 : 0, error = value - hit;
        marks[i] = hit * 255;
        if (x + 1 < columns) errors[i + 1] += error * 7 / 16;
        if (y + 1 < rows) { if (x) errors[i + columns - 1] += error * 3 / 16; errors[i + columns] += error * 5 / 16; if (x + 1 < columns) errors[i + columns + 1] += error / 16; }
      } else {
        const threshold = options.pattern === "stipple" ? noise(x, y) : options.pattern === "halftone" ? Math.hypot(fract(x / 5) - .5, fract(y / 5) - .5) * 1.42 : (bayer[(y % 4) * 4 + x % 4] + .5) / 16;
        marks[i] = shade > threshold ? 255 : 0;
      }
    } else {
      const px = (x + .5) * cellWidth, py = (y + .5) * cellHeight, u = px * Math.cos(angle) + py * Math.sin(angle), v = -px * Math.sin(angle) + py * Math.cos(angle);
      const bend = depth[i] * spacing * 2.2 * relief, wobble = Math.sin(u / 37) * .1 * spacing;
      const line = Math.abs(fract((v + bend + wobble) / spacing) - .5), cross = Math.abs(fract((u - bend * .7) / (spacing * 1.2)) - .5);
      const contour = Math.abs(fract(depth[i] * (96 / spacing)) - .5);
      const edge = x === 0 || y === 0 || x === columns - 1 || y === rows - 1 || !coverage[i - 1] || !coverage[i + 1] || !coverage[i - columns] || !coverage[i + columns];
      const broken = shade > .5 || noise(Math.floor(u / 12), Math.floor((v + bend) / spacing)) < shade + .35;
      const hit = options.treatment === "contour" ? contour < .055 + shade * .08 || edge : (line < .05 + shade * .33 && broken) || (options.treatment === "crosshatch" && shade > .42 && cross < (shade - .38) * .32);
      marks[i] = hit && noise(x, y) > .035 ? 255 : 0;
    }
  }
  return marks;
}

export type GlyphSet = "density" | "digits" | "letters";
export const SCULPTURE_GLYPHS = { density: " .,:;=+*#%@", digits: " .1273456890", letters: " .iltrcoEXMW" } as const;
/** Edge cells use a local shape gradient, independently of the interior density ramp. */
export function sculptureCharacters(frame: SculptureFrame, set: GlyphSet = "density", edgeMatching = true): string[] {
  const { coverage, light, grid: { columns, rows } } = frame, ramp = SCULPTURE_GLYPHS[set], out = new Array<string>(coverage.length).fill(" ");
  for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
    const i = y * columns + x;
    if (!coverage[i]) continue;
    out[i] = ramp[Math.max(1, Math.min(ramp.length - 1, Math.round(light[i] * (ramp.length - 2)) + 1))];
    if (!edgeMatching || set !== "density") continue;
    const sample = (dx: number, dy: number) => x + dx >= 0 && x + dx < columns && y + dy >= 0 && y + dy < rows ? coverage[i + dy * columns + dx] : 0;
    const gx = sample(1, -1) + 2 * sample(1, 0) + sample(1, 1) - sample(-1, -1) - 2 * sample(-1, 0) - sample(-1, 1);
    const gy = sample(-1, 1) + 2 * sample(0, 1) + sample(1, 1) - sample(-1, -1) - 2 * sample(0, -1) - sample(1, -1);
    if (Math.abs(gx) + Math.abs(gy) >= 3) out[i] = Math.abs(gx) > Math.abs(gy) * 1.7 ? "|" : Math.abs(gy) > Math.abs(gx) * 1.7 ? "_" : gx * gy > 0 ? "/" : "\\";
  }
  return out;
}

/** Compact opaque-cell path for a real, geometry-derived server/no-canvas fallback. */
export function sculpturePrintPath(marks: Uint8Array, columns: number) {
  let path = "";
  for (let i = 0; i < marks.length;) {
    if (!marks[i]) { i++; continue; }
    const x = i % columns, y = Math.floor(i / columns); let length = 1;
    while (x + length < columns && marks[i + length]) length++;
    path += `M${x} ${y}h${length}v1h-${length}z`; i += length;
  }
  return path;
}

/** Original, bounded geometry contract shared by the three print treatments. */
export type SculptureGeometryInput = {
  positions: ArrayLike<number>;
  triangles?: ArrayLike<number>;
  normals?: ArrayLike<number>;
};
export type SculptureGeometry = { positions: Float32Array; triangles: Uint16Array; normals: Float32Array };
export const SCULPTURE_LIMITS = { vertices: 16000, triangles: 20000, fileBytes: 8 * 1024 * 1024, imagePixels: 4000000, svgBytes: 128000 } as const;

export function sculptureGeometry(input: SculptureGeometryInput): SculptureGeometry {
  const length = input?.positions?.length ?? 0;
  if (!Number.isInteger(length) || length < 9 || length % 3 || length > SCULPTURE_LIMITS.vertices * 3) throw new Error("Use 3–16,000 vertices, with three coordinates per vertex.");
  const positions = Float32Array.from(input.positions);
  if (!positions.every(Number.isFinite)) throw new Error("The geometry contains a non-finite coordinate.");
  const count = length / 3, source = input.triangles ?? Array.from({ length: count }, (_, index) => index);
  if (!source.length || source.length % 3 || source.length > SCULPTURE_LIMITS.triangles * 3) throw new Error("Use a triangle mesh with at most 20,000 triangles.");
  const triangles = new Uint16Array(source.length);
  for (let i = 0; i < source.length; i++) {
    const value = source[i];
    if (!Number.isInteger(value) || value < 0 || value >= count) throw new Error("A triangle refers to a missing vertex.");
    triangles[i] = value;
  }
  const min = [Infinity, Infinity, Infinity], max = [-Infinity, -Infinity, -Infinity];
  for (let i = 0; i < length; i++) { const axis = i % 3; min[axis] = Math.min(min[axis], positions[i]); max[axis] = Math.max(max[axis], positions[i]); }
  const center = min.map((value, i) => (value + max[i]) / 2);
  let radius = 0;
  for (let i = 0; i < length; i += 3) radius = Math.max(radius, Math.hypot(positions[i] - center[0], positions[i + 1] - center[1], positions[i + 2] - center[2]));
  if (!Number.isFinite(radius) || radius < 1e-9) throw new Error("The geometry has no visible extent.");
  for (let i = 0; i < length; i++) positions[i] = (positions[i] - center[i % 3]) / radius;
  const normals = new Float32Array(length);
  if (input.normals) {
    if (input.normals.length !== length) throw new Error("Provide one normal for every vertex.");
    normals.set(Array.from(input.normals));
    if (!normals.every(Number.isFinite)) throw new Error("The geometry contains a non-finite normal.");
  } else {
    for (let i = 0; i < triangles.length; i += 3) {
      const a = triangles[i] * 3, b = triangles[i + 1] * 3, c = triangles[i + 2] * 3;
      const ux = positions[b] - positions[a], uy = positions[b + 1] - positions[a + 1], uz = positions[b + 2] - positions[a + 2];
      const vx = positions[c] - positions[a], vy = positions[c + 1] - positions[a + 1], vz = positions[c + 2] - positions[a + 2];
      const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
      for (const target of [a, b, c]) { normals[target] += nx; normals[target + 1] += ny; normals[target + 2] += nz; }
    }
  }
  for (let i = 0; i < length; i += 3) {
    const size = Math.hypot(normals[i], normals[i + 1], normals[i + 2]);
    if (size < 1e-8) normals[i + 2] = 1;
    else { normals[i] /= size; normals[i + 1] /= size; normals[i + 2] /= size; }
  }
  return { positions, triangles, normals };
}

/** A sampled luminance relief with transparent cells removed. No image is uploaded. */
export function sculptureFromPixels(image: { width: number; height: number; data: ArrayLike<number> }, relief = .22): SculptureGeometry {
  const { width, height, data } = image;
  if (!Number.isInteger(width) || !Number.isInteger(height) || width < 2 || height < 2 || width * height > SCULPTURE_LIMITS.imagePixels || data.length !== width * height * 4) throw new Error("Use an RGBA image from 2×2 up to 4 million pixels.");
  const columns = Math.min(72, width), rows = Math.min(72, height), positions: number[] = [], alpha: boolean[] = [], triangles: number[] = [];
  const aspect = width / height, depth = Number.isFinite(relief) ? Math.max(0, Math.min(.6, relief)) : .22;
  for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
    const px = Math.round(x / (columns - 1) * (width - 1)), py = Math.round(y / (rows - 1) * (height - 1)), at = (py * width + px) * 4;
    const light = (data[at] * .2126 + data[at + 1] * .7152 + data[at + 2] * .0722) / 255;
    positions.push((x / (columns - 1) * 2 - 1) * Math.min(aspect, 1), (1 - y / (rows - 1) * 2) / Math.max(aspect, 1), (light - .5) * depth);
    alpha.push(data[at + 3] >= 128);
  }
  for (let y = 0; y < rows - 1; y++) for (let x = 0; x < columns - 1; x++) {
    const a = y * columns + x, b = a + 1, c = a + columns, d = c + 1;
    if (alpha[a] && alpha[b] && alpha[c]) triangles.push(a, c, b);
    if (alpha[b] && alpha[c] && alpha[d]) triangles.push(b, c, d);
  }
  if (!triangles.length) throw new Error("The image is transparent or too small to form a surface. Choose an opaque image or a larger silhouette.");
  return sculptureGeometry({ positions, triangles });
}

"use client";

import * as React from "react";
import { animate, frameSteps, motionValue, type AnimationPlaybackControls, type Transition } from "motion";
import { getMotionTime, isMotionClockFrozen, registerMotionClock } from "@/lib/cojeev-motion/clock";
import { getSettingsSnapshot, getServerSettingsSnapshot, subscribeSettings, type SettingsSnapshot } from "@/lib/cojeev-motion/settings";
import { useReducedMotion } from "@/lib/cojeev-motion/use-reduced-motion";

/** The shared rhythm. Durations and stagger are seconds, matching Motion's API. */
export const motionTokens = {
  spring: {
    responsive: { type: "spring", stiffness: 360, damping: 32, mass: .85 },
    expressive: { type: "spring", stiffness: 260, damping: 22, mass: 1 },
