  initialWidth = 100,
  initialHeight = 20,
) {
  const width = useMotionValue(initialWidth),
    height = useMotionValue(initialHeight);
  React.useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => {
      const box = element.getBoundingClientRect();
      width.set(box.width);
      height.set(box.height);
    };
